    me = it.get("missing_effect")
    if me and me not in MISSING_EFFECTS:
        findings.append(f"items[{iid}]: missing_effect={me!r} が enum {MISSING_EFFECTS} 外")
    if me == "block":
        blocking_items.append(iid)
    dom = it.get("domain")
    if dom:
        domains_with_item.add(dom)

if findings:
    return findings, {}

